/**
 * A faithful-enough subset of CPython's `argparse` to drive this script:
 * optional long flags with a single value, the implicit `-h/--help` action,
 * `--flag=value` syntax, `--` end-of-options, required-argument checking and
 * the exact usage/error text argparse writes to stderr before exiting 2.
 *
 * Only the pieces the original program can reach are modelled; anything else
 * would be untestable guesswork.
 */

import { basename } from 'node:path';

/** Thrown internally so `error()` can unwind to the CLI entry point. */
export class ArgumentParserExit extends Error {
  constructor(status, output) {
    super(output);
    this.name = 'ArgumentParserExit';
    this.status = status;
    this.output = output;
  }
}

/** Python's `re` pattern argparse uses to spot negative-number-like tokens. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor({ optionStrings, dest, required = false, help = null, metavar = null, nargs = null }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.nargs = nargs;
  }

  /** The `A` in `--a A`: metavar, else the uppercased destination. */
  formatArgName() {
    if (this.metavar !== null) return this.metavar;
    return this.dest.toUpperCase();
  }

  /** How this option appears inside the bracketed usage line. */
  formatUsage() {
    const flag = this.optionStrings[0];
    if (this.nargs === 0) return flag;
    return `${flag} ${this.formatArgName()}`;
  }

  /** The left-hand column of the options help block. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    return this.optionStrings.map((flag) => `${flag} ${this.formatArgName()}`).join(', ');
  }
}

export class ArgumentParser {
  constructor({ prog = null, description = null } = {}) {
    this.prog = prog !== null ? prog : basename(process.argv[1] || 'prog');
    this.description = description;
    this.actions = [];

    // argparse installs the help action first, so it leads the usage line.
    this.actions.push(
      new Action({
        optionStrings: ['-h', '--help'],
        dest: 'help',
        nargs: 0,
        help: 'show this help message and exit',
      }),
    );
  }

  /**
   * Register an optional argument. `type` is accepted for parity with the
   * Python call site; `String` is the only converter this script needs.
   */
  add_argument(...flags) {
    const options = typeof flags[flags.length - 1] === 'object' && flags[flags.length - 1] !== null
      ? flags.pop()
      : {};
    const optionStrings = flags;
    const dest = options.dest !== undefined
      ? options.dest
      : optionStrings
          .find((flag) => flag.startsWith('--'))
          .replace(/^--/, '')
          .replace(/-/g, '_');

    const action = new Action({
      optionStrings,
      dest,
      required: options.required === true,
      help: options.help !== undefined ? options.help : null,
      metavar: options.metavar !== undefined ? options.metavar : null,
      nargs: options.nargs !== undefined ? options.nargs : null,
    });
    action.type = options.type !== undefined ? options.type : String;
    action.default = options.default !== undefined ? options.default : null;
    this.actions.push(action);
    return action;
  }

  /** `usage: prog [-h] --a A` — no trailing newline. */
  format_usage_line() {
    const parts = this.actions.map((action) =>
      action.required ? action.formatUsage() : `[${action.formatUsage()}]`,
    );
    return `usage: ${this.prog}${parts.length ? ' ' + parts.join(' ') : ''}`;
  }

  format_usage() {
    return this.format_usage_line() + '\n';
  }

  /** The full `--help` payload, matching argparse's two-space/two-gap layout. */
  format_help() {
    let text = this.format_usage() + '\n';
    if (this.description) text += this.description + '\n\n';
    text += 'options:\n';

    const rows = this.actions.map((action) => [action.formatInvocation(), action.help]);
    // argparse aligns help text at a column derived from the longest
    // invocation, capped so long flags wrap instead of pushing the column out.
    const maxInvocation = Math.max(...rows.map(([invocation]) => invocation.length));
    const helpColumn = Math.min(maxInvocation + 2, 24);

    for (const [invocation, help] of rows) {
      if (!help) {
        text += '  ' + invocation + '\n';
        continue;
      }
      if (invocation.length + 2 <= helpColumn) {
        text += '  ' + invocation.padEnd(helpColumn, ' ') + help + '\n';
      } else {
        text += '  ' + invocation + '\n' + ' '.repeat(2 + helpColumn) + help + '\n';
      }
    }
    return text;
  }

  print_help() {
    process.stdout.write(this.format_help());
  }

  /** argparse's `error()`: usage + message on stderr, then exit status 2. */
  error(message) {
    throw new ArgumentParserExit(
      2,
      `${this.format_usage()}${this.prog}: error: ${message}\n`,
    );
  }

  /** Look up an option string, honouring argparse's unique-prefix matching. */
  #findAction(flag) {
    for (const action of this.actions) {
      if (action.optionStrings.includes(flag)) return action;
    }
    if (!flag.startsWith('--')) return null;
    const matches = this.actions.filter((action) =>
      action.optionStrings.some((option) => option.startsWith('--') && option.startsWith(flag)),
    );
    if (matches.length === 1) return matches[0];
    return null;
  }

  /** True when a token should be read as an option rather than a value. */
  #looksLikeOption(token) {
    if (token === '' || !token.startsWith('-')) return false;
    if (token === '-' || token === '--') return true;
    // With no negative-number-like options declared, `-5` is a value.
    if (NEGATIVE_NUMBER.test(token)) return false;
    return true;
  }

  /**
   * Mirror of `parse_args`: parse what we know, then reject leftovers. The
   * required-argument check happens first, exactly as CPython orders it.
   */
  parse_args(argv = process.argv.slice(2)) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.dest === 'help') continue;
      namespace[action.dest] = action.default;
    }

    const seen = new Set();
    const extras = [];
    let optionsTerminated = false;

    for (let index = 0; index < argv.length; index += 1) {
      const token = argv[index];

      if (optionsTerminated || !this.#looksLikeOption(token)) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        optionsTerminated = true;
        continue;
      }

      // `--flag=value` carries its value inline.
      let flag = token;
      let inlineValue = null;
      const equals = token.indexOf('=');
      if (token.startsWith('--') && equals !== -1) {
        flag = token.slice(0, equals);
        inlineValue = token.slice(equals + 1);
      }

      const action = this.#findAction(flag);
      if (action === null) {
        extras.push(token);
        continue;
      }

      if (action.dest === 'help') {
        this.print_help();
        throw new ArgumentParserExit(0, '');
      }

      if (action.nargs === 0) {
        namespace[action.dest] = true;
        seen.add(action.dest);
        continue;
      }

      let value = inlineValue;
      if (value === null) {
        const next = argv[index + 1];
        if (next === undefined || this.#looksLikeOption(next)) {
          this.error(`argument ${flag}: expected one argument`);
        }
        value = next;
        index += 1;
      }
      namespace[action.dest] = action.type ? action.type(value) : value;
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

/**
 * Run `parse_args` with the process-level exit/stderr behaviour argparse has,
 * so the entry point stays as short as the Python original.
 */
export function runParser(parser, argv) {
  try {
    return parser.parse_args(argv);
  } catch (err) {
    if (err instanceof ArgumentParserExit) {
      if (err.status !== 0 && err.output) process.stderr.write(err.output);
      process.exit(err.status);
    }
    throw err;
  }
}

