export class WhooshError extends Error {
  constructor(message) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class FieldConfigurationError extends WhooshError {}

export class UnknownFieldError extends WhooshError {}

export class CompositionError extends WhooshError {}

