/**
 * The Porter stemming algorithm — the default `stemfn` behind
 * StemmingAnalyzer.
 *
 * Suffix stripping runs in five ordered steps, each gated on the "measure"
 * (m) of the stem: the number of vowel-consonant sequences that precede the
 * suffix. Rules only fire when enough stem survives to stay a real word,
 * which is why `relate -> relat` but `rate -> rate`.
 */

const step2list = {
  ational: 'ate', tional: 'tion', enci: 'ence', anci: 'ance', izer: 'ize',
  bli: 'ble', alli: 'al', entli: 'ent', eli: 'e', ousli: 'ous',
  ization: 'ize', ation: 'ate', ator: 'ate', alism: 'al', iveness: 'ive',
  fulness: 'ful', ousness: 'ous', aliti: 'al', iviti: 'ive', biliti: 'ble',
  logi: 'log',
};

const step3list = {
  icate: 'ic', ative: '', alize: 'al', iciti: 'ic', ical: 'ic', ful: '',
  ness: '',
};

// Consonant / vowel building blocks, assembled into the measure tests.
const c = '[^aeiou]';
const v = '[aeiouy]';
const C = c + '[^aeiouy]*';
const V = v + '[aeiou]*';

const mgr0 = new RegExp('^(' + C + ')?' + V + C);                       // m > 0
const meq1 = new RegExp('^(' + C + ')?' + V + C + '(' + V + ')?$');     // m == 1
const mgr1 = new RegExp('^(' + C + ')?' + V + C + V + C);               // m > 1
const s_v = new RegExp('^(' + C + ')?' + v);                            // has vowel

const step1a_1 = /^(.+?)(ss|i)es$/;
