/**
 * Core plumbing of the analysis package.
 *
 * An analyzer is a callable that turns a unicode string into a stream of
 * Token objects. Tokenizers start the stream, filters transform it, and the
 * `|` operator (here: `.or_(...)`) glues them into a CompositeAnalyzer.
 */

import { CompositionError } from '../errors.mjs';

/**
 * A single term in the stream.
 *
 * Whoosh reuses one Token instance for the whole stream as an optimisation,
 * so filters must not stash references to it. `clone()` exists for the rare
 * filter that genuinely needs a copy.
 */
export class Token {
  constructor({
    positions = false,
    chars = false,
    removestops = true,
    mode = '',
    ...extra
  } = {}) {
    this.positions = positions;
    this.chars = chars;
    this.stopped = false;
    this.boost = 1.0;
    this.removestops = removestops;
    this.mode = mode;
    Object.assign(this, extra);
  }

  copy() {
    return Object.assign(new Token(), this);
  }

  __repr__() {
    const parts = Object.keys(this)
      .sort()
      .map((key) => `${key}=${JSON.stringify(this[key])}`);
    return `Token(${parts.join(', ')})`;
  }
}

/**
 * Base class for anything that can take part in an analysis chain.
 *
 * Subclasses implement `call(value, options)`; `run(...)` is the public
 * entry point so a composite can invoke its members uniformly.
 */
export class Composable {
  /** Compose with the next stage, mirroring Python's `__or__`. */
  or_(other) {
    if (!(other instanceof Composable)) {
      throw new CompositionError(`${other} is not composable`);
    }
    return new CompositeAnalyzer(this, other);
  }

  /** True when this stage changes the surface form of a term. */
  has_morph() {
    return false;
  }

  /** Analyzers may need per-index setup; the default is a no-op. */
  clean() {}

  run(value, options = {}) {
    return this.call(value, options);
  }

  call(value, options) { // eslint-disable-line no-unused-vars
    throw new Error('Composable subclasses must implement call()');
  }

  __repr__() {
    return `${this.constructor.name}()`;
  }
}

/** Marker base class: the first stage of a chain, producing tokens. */
export class Tokenizer extends Composable {}

/** Marker base class: a stage that consumes and re-yields tokens. */
export class Filter extends Composable {
  call(tokens, options) { // eslint-disable-line no-unused-vars
    throw new Error('Filter subclasses must implement call()');
  }
}

/**
 * A tokenizer followed by one or more filters, flattened so that composing
 * an existing composite does not build a nested tree.
 */
export class CompositeAnalyzer extends Composable {
  constructor(...composables) {
    super();
    this.items = [];
    for (const composable of composables) {
      if (composable instanceof CompositeAnalyzer) {
        this.items.push(...composable.items);
      } else {
        this.items.push(composable);
      }
    }
  }

  or_(other) {
    return new CompositeAnalyzer(this, other);
  }

  /** Feed the value through the tokenizer, then each filter in turn. */
  *call(value, options = {}) {
    const [tokenizer, ...filters] = this.items;
    let stream = tokenizer.run(value, options);
    for (const filter of filters) {
      stream = filter.run(stream, options);
    }
    yield* stream;
  }

  has_morph() {
    return this.items.some((item) => item.has_morph());
  }

  clean() {
    for (const item of this.items) item.clean();
  }

  get length() {
    return this.items.length;
  }

  item(index) {
    return this.items[index];
  }

  __repr__() {
    return `${this.constructor.name}(${this.items.map((i) => i.__repr__()).join(', ')})`;
  }
}

/** Yield only the tokens a StopFilter left un-stopped. */
export function* unstopped(tokenStream) {
  for (const token of tokenStream) {
    if (!token.stopped) yield token;
  }
}

/** Collect an analyzer's output as plain strings — handy for inspection. */
export function analyzeToStrings(analyzer, value, options = {}) {
  const out = [];
  for (const token of analyzer.run(value, options)) out.push(token.text);
  return out;
}

