  if (expression instanceof RegExp) {
    const flags = expression.flags.includes('g') ? expression.flags : expression.flags + 'g';
    return new RegExp(expression.source, flags);
  }
  return new RegExp(expression, 'gu');
}

/**
 * Emit the whole input as one token. Used by ID fields, where the value is
 * an opaque key rather than prose.
 */
export class IDTokenizer extends Tokenizer {
  *call(value, options = {}) {
    const {
      positions = false,
      chars = false,
      keeporiginal = false,
      removestops = true,
      start_pos = 0,
      start_char = 0,
      mode = '',
    } = options;

    const token = new Token({ positions, chars, removestops, mode });
    token.text = value;
    if (keeporiginal) token.original = value;
    if (positions) token.pos = start_pos + 1;
    if (chars) {
      token.startchar = start_char;
      token.endchar = start_char + value.length;
    }
    yield token;
  }
}

/**
 * Split text with a regular expression.
 *
 * With `gaps` false (the default) each match *is* a token; with `gaps` true
 * the matches are the separators and the text between them is tokenized.
 */
export class RegexTokenizer extends Tokenizer {
  constructor({ expression = default_pattern, gaps = false } = {}) {
    super();
    this.expression = compile(expression);
    this.gaps = gaps;
  }

  equals(other) {
    return (
      other instanceof RegexTokenizer &&
      other.expression.source === this.expression.source &&
      other.gaps === this.gaps
    );
  }

  *call(value, options = {}) {
    const {
      positions = false,
      chars = false,
      keeporiginal = false,
      removestops = true,
      start_pos = 0,
      start_char = 0,
      tokenize = true,
      mode = '',
    } = options;

    const token = new Token({ positions, chars, removestops, mode });

    // `tokenize=False` is how whoosh asks for the value to pass straight
    // through, e.g. when a query term is already a single term.
    if (!tokenize) {
      token.original = value;
      token.text = value;
      token.boost = 1.0;
      if (positions) token.pos = start_pos;
      if (chars) {
        token.startchar = start_char;
        token.endchar = start_char + value.length;
      }
      yield token;
      return;
    }

    const spans = this.gaps ? this.#gapSpans(value) : this.#matchSpans(value);
    let position = start_pos;
    for (const [text, startChar, endChar] of spans) {
      if (this.gaps && text.length === 0) continue;
      token.text = text;
      token.boost = 1.0;
      token.stopped = false;
      if (keeporiginal) token.original = token.text;
      if (positions) {
        token.pos = position;
        position += 1;
      }
      if (chars) {
        token.startchar = start_char + startChar;
        token.endchar = start_char + endChar;
      }
      yield token;
    }
  }

  /** Every regex match becomes a token. */
  #matchSpans(value) {
    const spans = [];
    this.expression.lastIndex = 0;
    let match = this.expression.exec(value);
    while (match !== null) {
      spans.push([match[0], match.index, match.index + match[0].length]);
      // Guard against a zero-width match looping forever.
      if (match[0].length === 0) this.expression.lastIndex += 1;
      match = this.expression.exec(value);
    }
    return spans;
  }

  /** Every regex match is a separator; the text between becomes tokens. */
  #gapSpans(value) {
    const spans = [];
    let cursor = 0;
    this.expression.lastIndex = 0;
    let match = this.expression.exec(value);
    while (match !== null) {
      spans.push([value.slice(cursor, match.index), cursor, match.index]);
      cursor = match.index + match[0].length;
      if (match[0].length === 0) this.expression.lastIndex += 1;
      match = this.expression.exec(value);
    }
    spans.push([value.slice(cursor), cursor, value.length]);
    return spans;
  }

  __repr__() {
    return `${this.constructor.name}(expression=${this.expression.source}, gaps=${this.gaps ? 'True' : 'False'})`;
  }
}

/** Split on runs of whitespace. */
export class SpaceSeparatedTokenizer extends RegexTokenizer {
  constructor() {
    super({ expression: /[^ \t\r\n]+/gu });
  }
}

/** Split on commas, trimming the surrounding whitespace. */
export class CommaSeparatedTokenizer extends RegexTokenizer {
  constructor() {
    super({ expression: /[^,]+/gu });
  }

  *call(value, options = {}) {
    for (const token of super.call(value, options)) {
      token.text = token.text.trim();
      yield token;
    }
  }
}

