/**
 * Token filters: stages that sit after the tokenizer and rewrite, drop or
 * annotate the terms flowing through.
 */

import { Filter } from './acore.mjs';
import { STOP_WORDS } from '../lang/stopwords.mjs';

/** Yield the stream untouched. Useful as a neutral element in a chain. */
export class PassFilter extends Filter {
  *call(tokens) {
    yield* tokens;
  }
}

/**
 * Lowercase every term.
 *
 * This is what makes indexing case-insensitive, and it must run before the
 * stop list and the stemmer, both of which expect lowercase input.
 */
export class LowercaseFilter extends Filter {
  *call(tokens) {
    for (const token of tokens) {
      token.text = token.text.toLowerCase();
      yield token;
    }
  }
}

/** Strip leading and trailing whitespace from every term. */
export class StripFilter extends Filter {
  *call(tokens) {
    for (const token of tokens) {
      token.text = token.text.trim();
      yield token;
    }
  }
}

/**
 * Remove stop words and terms outside a length range.
 *
 * When a token's `removestops` is false the token is marked `stopped` and
 * still yielded — query parsing needs to know a word was *there* so that
 * phrase positions stay aligned.
 */
export class StopFilter extends Filter {
  constructor({
    stoplist = STOP_WORDS,
    minsize = 2,
    maxsize = null,
    renumber = true,
    lang = null,
  } = {}) {
    super();
    this.stops = stoplist === null || stoplist === undefined
      ? new Set()
      : new Set(stoplist);
    this.min = minsize;
    this.max = maxsize;
    this.renumber = renumber;
    this.lang = lang;
  }

  *call(tokens) {
    const { stops, min, max, renumber } = this;
    let position = 0;

    for (const token of tokens) {
      const text = token.text;
      const tooShort = text.length < min;
      const tooLong = max !== null && text.length > max;

      if (!tooShort && !tooLong && !stops.has(text)) {
        // Renumbering closes the gaps left by removed words.
        if (renumber && token.positions) {
          const gapped = token.pos !== position;
          token.pos = position;
          if (gapped) token.pos = position;
        }
        position += 1;
        token.stopped = false;
        yield token;
      } else if (!token.removestops) {
        if (renumber && token.positions) token.pos = position;
        position += 1;
        token.stopped = true;
        yield token;
      }
    }
  }

  __repr__() {
    return `${this.constructor.name}(stops=<${this.stops.size} words>, min=${this.min}, max=${this.max === null ? 'None' : this.max})`;
  }
}

/**
 * Apply a boost multiplier to every term, e.g. to weight a field's contents
 * above another's.
 */
export class BoostTextFilter extends Filter {
  constructor(boost = 1.0) {
    super();
    this.boost = boost;
  }

  *call(tokens) {
    for (const token of tokens) {
      token.boost *= this.boost;
      yield token;
    }
  }
}

/** Drop terms that a predicate rejects. */
export class TeeFilter extends Filter {
  constructor(predicate) {
    super();
    this.predicate = predicate;
  }

  *call(tokens) {
    for (const token of tokens) {
      if (this.predicate(token.text)) yield token;
    }
  }
}

