/**
 * Morphological filters — stages that rewrite a term to a normalised root so
 * that "rendering", "renders" and "rendered" all match one index term.
 */

import { Filter } from './acore.mjs';
import { stem as porterStem } from '../lang/porter.mjs';

/**
 * A bounded memo table.
 *
 * Stemming the same handful of words repeatedly dominates indexing cost, so
 * whoosh wraps the stem function in an LRU cache. Once the cache is full the
 * least recently used entry is evicted; `cachesize` of 0 or below disables
 * caching entirely, and a negative value means "unbounded".
 */
class LruCache {
  constructor(maxsize) {
    this.maxsize = maxsize;
    this.entries = new Map();
  }

  get(key, compute) {
    if (this.maxsize === 0) return compute(key);

    if (this.entries.has(key)) {
      const value = this.entries.get(key);
      // Re-insert to mark the key as most recently used.
      this.entries.delete(key);
      this.entries.set(key, value);
      return value;
    }

    const value = compute(key);
    this.entries.set(key, value);
    if (this.maxsize > 0 && this.entries.size > this.maxsize) {
      const oldest = this.entries.keys().next().value;
      this.entries.delete(oldest);
    }
    return value;
  }

  clear() {
    this.entries.clear();
  }
}

/**
 * Stem every term with `stemfn`, skipping any term in `ignore`.
 *
 * Because this filter changes the surface form of terms, `has_morph()` is
 * true — the query parser uses that to decide whether a wildcard term can be
 * expanded safely.
 */
export class StemFilter extends Filter {
  constructor({
    stemfn = porterStem,
    lang = null,
    ignore = null,
    cachesize = 50000,
  } = {}) {
    super();
    this.stemfn = stemfn;
    this.lang = lang;
    this.ignore = ignore === null || ignore === undefined ? new Set() : new Set(ignore);
    this.cachesize = cachesize;
    this.cache = new LruCache(cachesize);
  }

  has_morph() {
    return true;
  }

  /** Reset the memo table; called when an analyzer is reused for a new index. */
  clean() {
    this.cache.clear();
  }

  *call(tokens) {
    const { stemfn, ignore, cache } = this;
    for (const token of tokens) {
      // Stopped tokens are placeholders, so leave their text alone.
      if (!token.stopped) {
        const text = token.text;
        if (!ignore.has(text)) {
          token.text = cache.get(text, stemfn);
        }
      }
      yield token;
    }
  }

  __repr__() {
    return `${this.constructor.name}(stemfn=${this.stemfn.name || 'stem'}, lang=${this.lang === null ? 'None' : `'${this.lang}'`})`;
  }
}

/** Expose the default stemmer so callers can pass it explicitly. */
export { porterStem as stem };

