import { IDTokenizer, RegexTokenizer, default_pattern } from './tokenizers.mjs';
import { LowercaseFilter, StopFilter, StripFilter, PassFilter } from './filters.mjs';
import { StemFilter } from './morph.mjs';
import { stem } from '../lang/porter.mjs';
import { STOP_WORDS } from '../lang/stopwords.mjs';

/** Treat the whole value as one term, optionally lowercasing it. */
export function IDAnalyzer({ lowercase = false } = {}) {
  const tokenizer = new IDTokenizer();
  if (lowercase) return tokenizer.or_(new LowercaseFilter());
  return new CompositeAnalyzer(tokenizer, new PassFilter());
}

/** Split on whitespace only, leaving case and punctuation intact. */
export function KeywordAnalyzer({ lowercase = false, commas = false } = {}) {
  const tokenizer = new RegexTokenizer({
    expression: commas ? /[^,]+/gu : /[^ \t\r\n]+/gu,
  });
  let chain = commas ? tokenizer.or_(new StripFilter()) : new CompositeAnalyzer(tokenizer, new PassFilter());
  if (lowercase) chain = chain.or_(new LowercaseFilter());
  return chain;
}

/** Just the tokenizer — the building block the others extend. */
export function RegexAnalyzer({ expression = /\w+(\.?\w+)*/gu, gaps = false } = {}) {
  return new CompositeAnalyzer(new RegexTokenizer({ expression, gaps }), new PassFilter());
}

/** Tokenize and lowercase; no stop words, no stemming. */
export function SimpleAnalyzer({ expression = default_pattern, gaps = false } = {}) {
  return new RegexTokenizer({ expression, gaps }).or_(new LowercaseFilter());
}

/**
 * The default text analyzer: tokenize, lowercase, then drop stop words and
 * out-of-range term lengths.
 */
export function StandardAnalyzer({
  expression = default_pattern,
  stoplist = STOP_WORDS,
  minsize = 2,
  maxsize = null,
  gaps = false,
} = {}) {
  const chain = new RegexTokenizer({ expression, gaps }).or_(new LowercaseFilter());
  if (stoplist === null || stoplist === undefined) return chain;
  return chain.or_(new StopFilter({ stoplist, minsize, maxsize }));
}

/**
 * StandardAnalyzer plus Porter stemming.
 *
 * Order matters: lowercasing feeds the stop list, and the stop list runs
 * before the stemmer so that stop words are matched in their original form
 * rather than as stems.
 */
export function StemmingAnalyzer({
  expression = default_pattern,
  stoplist = STOP_WORDS,
  minsize = 2,
  maxsize = null,
  gaps = false,
  stemfn = stem,
  ignore = null,
  cachesize = 50000,
} = {}) {
  const tokenizer = new RegexTokenizer({ expression, gaps });
  let chain = tokenizer.or_(new LowercaseFilter());
  if (stoplist !== null && stoplist !== undefined) {
    chain = chain.or_(new StopFilter({ stoplist, minsize, maxsize }));
  }
  return chain.or_(new StemFilter({ stemfn, ignore, cachesize }));
}

