/**
 * Posting formats: they decide what per-term information a field records in
 * the index, and each owns the analyzer that produces those terms.
 *
 * The choice is a storage/feature trade-off — Existence is the smallest and
 * supports only "does this term occur", Positions is the largest and is what
 * phrase search needs.
 */

export class Format {
  /** Subclasses set this when they record term positions. */
  static posting_size = -1;

  constructor({ analyzer = null, field_boost = 1.0, options = {} } = {}) {
    this.analyzer = analyzer;
    this.field_boost = field_boost;
    this.options = options;
  }

  /** Whether this format can answer phrase queries. */
  get supports_positions() {
    return false;
  }

  /** Run the field's analyzer over a value, yielding tokens. */
  *analyze(value, options = {}) {
    if (this.analyzer === null) {
      throw new Error(`${this.constructor.name} has no analyzer`);
    }
    yield* this.analyzer.run(value, options);
  }

  /** Terms only, with no per-term payload — the shape a subclass refines. */
  word_values(value, options = {}) {
    const out = [];
    for (const token of this.analyze(value, options)) {
      if (token.stopped) continue;
      out.push([token.text, 1, this.field_boost * token.boost, null]);
    }
    return out;
  }

  clean() {
    if (this.analyzer !== null) this.analyzer.clean();
  }

  __repr__() {
    return `${this.constructor.name}(boost=${this.field_boost})`;
  }
}

/** Record only that a term occurs in the document. */
export class Existence extends Format {
  static posting_size = 0;

  word_values(value, options = {}) {
    const seen = new Set();
    const out = [];
    for (const token of this.analyze(value, options)) {
      if (token.stopped || seen.has(token.text)) continue;
      seen.add(token.text);
      out.push([token.text, 1, this.field_boost, null]);
    }
    return out;
  }
}

/** Record how many times each term occurs — enough for BM25 scoring. */
export class Frequency extends Format {
  static posting_size = 0;

  word_values(value, options = {}) {
    const frequencies = new Map();
    for (const token of this.analyze(value, options)) {
      if (token.stopped) continue;
      frequencies.set(token.text, (frequencies.get(token.text) || 0) + 1);
    }
    return [...frequencies].map(([text, freq]) => [
      text,
      freq,
      freq * this.field_boost,
      null,
    ]);
  }
}

/** Record every position at which each term occurs; enables phrase search. */
export class Positions extends Format {
  static posting_size = -1;

  get supports_positions() {
    return true;
  }

  word_values(value, options = {}) {
    const positions = new Map();
    const merged = { ...options, positions: true };
    for (const token of this.analyze(value, merged)) {
      if (token.stopped) continue;
      if (!positions.has(token.text)) positions.set(token.text, []);
      positions.get(token.text).push(token.pos);
    }
    return [...positions].map(([text, poslist]) => [
      text,
      poslist.length,
      poslist.length * this.field_boost,
      poslist,
    ]);
  }
}

/** Positions plus the character span of each occurrence, for highlighting. */
export class Characters extends Positions {
  word_values(value, options = {}) {
    const spans = new Map();
    const merged = { ...options, positions: true, chars: true };
    for (const token of this.analyze(value, merged)) {
      if (token.stopped) continue;
      if (!spans.has(token.text)) spans.set(token.text, []);
      spans.get(token.text).push([token.pos, token.startchar, token.endchar]);
    }
    return [...spans].map(([text, items]) => [
      text,
      items.length,
      items.length * this.field_boost,
      items,
    ]);
  }
}

