/**
 * Field types and the Schema that binds names to them.
 *
 * A FieldType pairs an analyzer-carrying Format with the flags that decide
 * how the field is indexed and stored. Schema is an ordered, name-keyed
 * collection of those types.
 */

import { FieldConfigurationError, UnknownFieldError } from './errors.mjs';
import { repr, sortedStrings, typeName } from '../pycompat.mjs';
import { Format, Existence, Frequency, Positions, Characters } from './formats.mjs';
import {
  IDAnalyzer,
  KeywordAnalyzer,
  StandardAnalyzer,
  CommaSeparatedTokenizer,
  LowercaseFilter,
} from './analysis/index.mjs';

/**
 * Base class for all field types.
 *
 * `format` carries the analyzer, so `field.analyzer` is a shortcut through
 * it rather than a second copy of the reference.
 */
export class FieldType {
  constructor({
    format = null,
    analyzer = null,
    vector = null,
    scorable = false,
    stored = false,
    unique = false,
    multitoken_query = 'default',
    sortable = false,
    column_type = null,
    spelling = false,
  } = {}) {
    this.format = format;
    this.vector = vector;
    this.scorable = scorable;
    this.stored = stored;
    this.unique = unique;
    this.multitoken_query = multitoken_query;
    this.sortable = sortable;
    this.column_type = column_type;
    this.spelling = spelling;
    this.indexed = format !== null;

    if (analyzer !== null && this.format !== null) {
      this.format.analyzer = analyzer;
    }
  }

  get analyzer() {
    return this.format === null ? null : this.format.analyzer;
  }

  set analyzer(value) {
    if (this.format === null) {
      throw new FieldConfigurationError(`${this.constructor.name} field has no format`);
    }
    this.format.analyzer = value;
  }

  /** True when the field's analyzer rewrites terms (e.g. a stemmer). */
  has_morph() {
    return this.format !== null && this.format.analyzer !== null
      ? this.format.analyzer.has_morph()
      : false;
  }

  /** True when this field can serve phrase queries. */
  supports(name) {
    if (name === 'positions') return this.format !== null && this.format.supports_positions;
    if (name === 'characters') return this.format instanceof Characters;
    return false;
  }

  /** Turn a document value into `[term, freq, weight, payload]` tuples. */
  index(value, options = {}) {
    if (!this.indexed) {
      throw new Error(`${this.constructor.name} field is not indexed`);
    }
    return this.format.word_values(value, { ...options, mode: 'index' });
  }

  /** Analyze a query string into its terms. */
  process_text(value, options = {}) {
    if (this.format === null || this.format.analyzer === null) {
      throw new Error(`${this.constructor.name} field has no analyzer`);
    }
    const out = [];
    for (const token of this.format.analyzer.run(value, { mode: 'query', ...options })) {
      if (!token.stopped) out.push(token.text);
    }
    return out;
  }

  /** Normalise a single query term the way indexing would have. */
  to_bytes(value) {
    return String(value);
  }

  clean() {
    if (this.format !== null) this.format.clean();
  }

  __repr__() {
    return `${this.constructor.name}(format=${this.format === null ? 'None' : this.format.__repr__()}, stored=${this.stored ? 'True' : 'False'}, unique=${this.unique ? 'True' : 'False'})`;
  }
}

/**
 * Free text: tokenized, indexed, and by default position-aware so that
 * phrase queries work.
 */
export class TEXT extends FieldType {
  constructor({
    analyzer = null,
    phrase = true,
    chars = false,
    field_boost = 1.0,
    multitoken_query = 'default',
    spelling = false,
    sortable = false,
    lang = null,
    vector = null,
    stored = false,
  } = {}) {
    const chosen = analyzer !== null ? analyzer : StandardAnalyzer();

    // The format is picked from the richest feature the field was asked for.
    let FormatClass = Frequency;
    if (chars) FormatClass = Characters;
    else if (phrase) FormatClass = Positions;

    super({
      format: new FormatClass({ analyzer: chosen, field_boost }),
      scorable: true,
      stored,
      sortable,
      spelling,
      multitoken_query,
      vector,
    });

    this.phrase = phrase;
    this.chars = chars;
    this.lang = lang;
  }
}

/** A single opaque token: an identifier, path or URL. */
export class ID extends FieldType {
  constructor({ stored = false, unique = false, field_boost = 1.0, sortable = false, analyzer = null } = {}) {
    super({
      format: new Existence({ analyzer: analyzer !== null ? analyzer : IDAnalyzer(), field_boost }),
      stored,
      unique,
      sortable,
    });
  }
}

/** A comma-separated list of opaque tokens. */
export class IDLIST extends FieldType {
  constructor({ stored = false, unique = false, expression = null, field_boost = 1.0 } = {}) {
    const analyzer = expression !== null
      ? expression
      : new CommaSeparatedTokenizer().or_(new LowercaseFilter());
    super({
      format: new Existence({ analyzer, field_boost }),
      stored,
      unique,
    });
  }
}

/** Space-separated keywords, indexed with their frequencies. */
export class KEYWORD extends FieldType {
  constructor({
    stored = false,
    lowercase = false,
    commas = false,
    scorable = false,
    unique = false,
    field_boost = 1.0,
    sortable = false,
    vector = null,
    analyzer = null,
  } = {}) {
    const chosen = analyzer !== null ? analyzer : KeywordAnalyzer({ lowercase, commas });
    super({
      format: new Frequency({ analyzer: chosen, field_boost }),
      scorable,
      stored,
      unique,
      sortable,
      vector,
    });
  }
}

/** Stored but never indexed — retrievable payload only. */
export class STORED extends FieldType {
  constructor() {
    super({ stored: true });
    this.indexed = false;
  }
}

/** A true/false field, indexed as the single term "t" or "f". */
export class BOOLEAN extends FieldType {
  constructor({ stored = false, field_boost = 1.0 } = {}) {
    super({
      format: new Existence({ analyzer: IDAnalyzer(), field_boost }),
      stored,
    });
  }

  to_bytes(value) {
    return value ? 't' : 'f';
  }
}

/**
 * The mapping of field names to field types.
 *
 * Fields are kept in sorted order, which is why `names()` and therefore
 * `repr(schema)` are deterministic regardless of construction order.
 */
export class Schema {
  /** `new Schema({ content: TEXT(...) })` mirrors `Schema(content=...)`. */
  constructor(fields = {}) {
    this._fields = new Map();
    this._dyn_fields = new Map();

    for (const name of sortedStrings(Object.keys(fields))) {
      this.add(name, fields[name]);
    }
  }

  /** Sorted list of the static field names. */
  names() {
    return sortedStrings([...this._fields.keys()]);
  }

  /** `[name, fieldtype]` pairs in name order. */
  items() {
    return this.names().map((name) => [name, this._fields.get(name)]);
  }

  /** Register a field, validating the name and the type. */
  add(name, fieldtype, glob = false) {
    if (name.startsWith('_')) {
      throw new FieldConfigurationError('Field names cannot start with an underscore');
    }
    if (name.includes(' ')) {
      throw new FieldConfigurationError('Field names cannot contain spaces');
    }
    if (this._fields.has(name) || (glob && this._dyn_fields.has(name))) {
      throw new FieldConfigurationError(`Schema already has a field ${repr(name)}`);
    }

    // A bare class (rather than an instance) is instantiated with defaults,
    // so `Schema({ path: ID })` behaves like `Schema({ path: ID() })`.
    let resolved = fieldtype;
    if (typeof resolved === 'function') resolved = new resolved();
    if (!(resolved instanceof FieldType)) {
      throw new FieldConfigurationError(`${repr(fieldtype)} is not a FieldType object`);
    }

    if (glob) {
      this._dyn_fields.set(name, resolved);
    } else {
      this._fields.set(name, resolved);
    }
  }

  /** Remove a field; unknown names are ignored, as in whoosh. */
  remove(name) {
    if (this._fields.has(name)) {
      this._fields.delete(name);
    } else if (this._dyn_fields.has(name)) {
      this._dyn_fields.delete(name);
    } else {
      throw new UnknownFieldError(`No field named ${repr(name)}`);
    }
  }

  /** Look up a field type by name; throws for unknown names. */
  get(name) {
    if (this._fields.has(name)) return this._fields.get(name);
    if (this._dyn_fields.has(name)) return this._dyn_fields.get(name);
    throw new UnknownFieldError(`No field named ${repr(name)}`);
  }

  has(name) {
    return this._fields.has(name) || this._dyn_fields.has(name);
  }

  get size() {
    return this._fields.size;
  }

  /** Names of the fields whose contents are kept for retrieval. */
  stored_names() {
    return this.names().filter((name) => this._fields.get(name).stored);
  }

  /** Names of the fields that are scored rather than just filtered. */
  scorable_names() {
    return this.names().filter((name) => this._fields.get(name).scorable);
  }

  clean() {
    for (const field of this._fields.values()) field.clean();
  }

  *[Symbol.iterator]() {
    for (const name of this.names()) yield this._fields.get(name);
  }

  /** `<Schema: ['content']>` — the exact text the script prints. */
  __repr__() {
    return `<${typeName(this)}: ${repr(this.names())}>`;
  }

  toString() {
    return this.__repr__();
  }
}

export { Format, Existence, Frequency, Positions, Characters };

