/**
 * Minimal re-creation of the CPython runtime behaviours the original script
 * leans on: `repr()` formatting and `%`-style interpolation.
 *
 * Keeping this in one place means the rest of the library can talk about
 * "repr" exactly the way the Python source did.
 */

/** Characters Python escapes inside a string literal, mapped to their escape. */
const STRING_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/**
 * repr() for a string, following CPython's quote-selection rule: single
 * quotes are preferred, but a string containing a single quote and no double
 * quote is wrapped in double quotes instead.
 */
export function reprString(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let out = '';
  for (const ch of value) {
    if (ch === quote) {
      out += '\\' + ch;
      continue;
    }
    const escape = STRING_ESCAPES.get(ch);
    if (escape !== undefined) {
      out += escape;
      continue;
    }
    const code = ch.codePointAt(0);
    if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
      continue;
    }
    out += ch;
  }
  return quote + out + quote;
}

/** repr() for a list, i.e. `['a', 'b']` with ", " between the items. */
export function reprList(items) {
  return '[' + items.map((item) => repr(item)).join(', ') + ']';
}

/** repr() dispatcher covering the value kinds this project produces. */
export function repr(value) {
  if (typeof value === 'string') return reprString(value);
  if (Array.isArray(value)) return reprList(value);
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'number') return reprNumber(value);
  if (typeof value === 'object' && typeof value.__repr__ === 'function') {
    return value.__repr__();
  }
  return String(value);
}

/** repr() for a number, reproducing Python's int/float split. */
export function reprNumber(value) {
  if (Number.isInteger(value)) return String(value);
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  return String(value);
}

/**
 * Sort strings the way Python's `sorted()` does: by code point, not by the
 * host locale.
 */
export function sortedStrings(values) {
  return [...values].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
}

/** The name Python would report as `type(obj).__name__`. */
export function typeName(obj) {
  if (obj === null || obj === undefined) return 'NoneType';
  return obj.constructor ? obj.constructor.name : typeof obj;
}

