console.log('index   :', s.get('body').index('the cats are running and running'));
try { s.add('_bad', new TEXT()); } catch (e) { console.log('guard   :', e.name, '-', e.message); }
try { s.add('title', new TEXT()); } catch (e) { console.log('guard   :', e.name, '-', e.message); }
console.log('class ok:', new Schema({ path: ID }).names());
